const body = $json.body || $json;
if ($env.PESKIDS_SWIM_MISSION_AUTOMATION_ENABLED !== 'true') return [];
if (body.assignment_mode && body.assignment_mode !== 'auto_assign_safe') throw new Error('Only auto_assign_safe is executable in this workflow');
for (const key of ['student_id','mission_slug','rule_id','idempotency_key']) { if (!body[key]) throw new Error('Missing ' + key); }
return [{ json: { student_id: body.student_id, mission_slug: body.mission_slug, reason: body.reason || null, due_at: body.due_at || null, assignment_mode: 'auto_assign_safe', rule_id: body.rule_id, workflow_id: 'peskids-swim-mission-auto-assign', idempotency_key: body.idempotency_key } }];
